let route=initialHash[0]||(db.play?.space==='organizer'?'dashboard':'home'),tourFilter='all',requestFilter='pending',rankMetric='oneEighties',selectedTour=1,matchId=Number(initialHash[1])||1,scoreText='',navOpen=false,playerSearch='',modalOrigin=null;
