const T=id=>db.tournaments.find(t=>t.id===Number(id))||db.tournaments[0];
const short=id=>P(id).name.split(' ')[0];
const avatar=(id,cls='')=>`<span class="avatar ${cls}" style="${id&&id%3===0?'background:#3a332a;border-color:#65543a;color:#d2bea3':id&&id%3===1?'background:#2c3b32;border-color:#465e4e;color:#b9d3c1':''}">${esc(initials(typeof id==='number'?P(id).name:id))}</span>`;
const scopedRegistrationRequests=()=>db.requests.filter(request=>{
  if (request.type!=='entry') return scopeId()===null;
  const tournament=db.tournaments.find(item=>Number(item.id)===Number(request.tournament));
  return String(tournament?.clubId??'global')===String(scopeId()??'global');
});
const pending=()=>scopedRegistrationRequests().filter(r=>r.status==='pending').length;
const save=()=>{try{localStorage.setItem('puinruimers-demo-v3',JSON.stringify(db));}catch{toast('Opslaan is niet beschikbaar in deze browser.');}};
const log=msg=>{db.activity.unshift(msg);db.activity=db.activity.slice(0,10);};
const admin=()=>db.role==='admin';
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const tourStatus=t=>badge({active:'Actief',open:'Inschrijving open',draft:'In planning',finished:'Afgelopen'}[t.status],{active:'live',open:'pending',draft:'blue',finished:'finished'}[t.status]);
const liveBadge=m=>m.status==='live'?`<span class="badge live"><i class="live-dot"></i> Live</span>`:badge('Afgelopen','finished');
const date=d=>new Intl.DateTimeFormat('nl-NL',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00'));
const button=(label,act,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${act}" ${extra}>${label}</button>`;
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3300);}
function go(to){const parts=String(to).split('/');const next=parts[0]||'home';if(route!==next&&rooms?.stopMedia)rooms.stopMedia();route=next;pageParam=parts.slice(1).join('/');if(['match','spectator','overlay'].includes(route)&&pageParam)matchId=Number(pageParam)||1;navOpen=false;scoreText='';const hash=['match','spectator','overlay'].includes(route)?`#${route}/${matchId}`:`#${route}${pageParam?'/'+pageParam:''}`;if(location.hash!==hash)history.pushState({},'',hash);render();window.scrollTo({top:0});}
function followHash(){navOpen=false;const parts=location.hash.slice(1).split('/');route=parts[0]||'home';pageParam=parts.slice(1).join('/');if(['match','spectator','overlay'].includes(route))matchId=Number(pageParam)||1;rooms?.stopMedia?.();render();}
window.addEventListener('popstate',followHash);
window.addEventListener('hashchange',followHash);
function header(title,sub,action='',eye='Dartflow · Royal Oche'){return `<div class="page-heading"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${action}</div></div>`;}
function metric(label,value,ic,trend,spark=false){return `<div class="metric"><div class="metric-top"><span class="metric-label">${label}</span>${icon(ic)}</div><div class="metric-bottom"><span class="metric-number">${value}</span>${spark?`<svg class="spark" viewBox="0 0 80 28" aria-hidden="true"><path d="m1 25 10-5 9 3 10-11 9 3 10-7 10 3L79 2" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="m1 25 10-5 9 3 10-11 9 3 10-7 10 3L79 2v26H1Z" fill="currentColor" opacity=".1"/></svg>`:`<span class="metric-trend">${trend}</span>`}</div></div>`;}
function sectionHeading(title,link,act,extra=''){return `<div class="section-heading"><div class="section-title"><h2>${title}</h2>${extra}</div>${link?`<button class="text-link" data-action="${act}">${link}${icon('right')}</button>`:''}</div>`;}
function boardCard(m){return `<article class="board-card"><div class="board-top"><span>Bord ${m.board}</span>${liveBadge(m)}</div><div class="board-visual"><img src="assets/dartboard.svg" alt="Dartbord"></div><div class="board-mode">${icon(m.mode==='Online'?'wifi':m.mode==='Hybride'?'bolt':'pin')}${esc(m.mode)}</div><div class="board-match"><div class="board-players"><span>${esc(short(m.players[0]))}</span><span>${esc(short(m.players[1]))}</span></div><div class="board-legs"><span>${m.legs[0]}</span><span>–</span><span>${m.legs[1]}</span></div><div class="board-format">BEST OF ${m.bestOf} LEGS · ${m.startScore}</div></div><div class="board-remaining"><div><strong>${m.remaining[0]}</strong><small>RESTEREND</small></div><div><strong>${m.remaining[1]}</strong><small>RESTEREND</small></div></div><button class="board-open" data-action="open-match" data-id="${m.id}">${m.status==='live'?'Bekijk wedstrijd':'Bekijk uitslag'}${icon('arrow')}</button></article>`;}
function compactTour(t){return `<article class="tournament-compact"><div class="tournament-body"><div class="tournament-top"><span class="tournament-name"><span class="tour-icon">${icon('trophy')}</span>${esc(t.name)}</span>${tourStatus(t)}</div><div class="tournament-meta"><span>${icon('users')}${t.players}/${t.capacity} spelers</span><span>${icon('bracket')}${esc(t.format)}</span><span>${icon('target')}${t.score} · Dubbel uit</span></div><div class="progress-label"><span>${t.status==='active'?'Poulefase':t.status==='open'?'Inschrijvingen':'Voorbereiding'}</span><span>${t.status==='open'?Math.round(t.players/t.capacity*100):t.progress}%</span></div><div class="progress"><span style="width:${t.status==='open'?t.players/t.capacity*100:t.progress}%"></span></div></div><div class="tournament-footer"><span>${icon('calendar')} ${date(t.date)}</span><button class="text-link" data-action="tour-detail" data-id="${t.id}">Bekijk toernooi ${icon('right')}</button></div></article>`;}
function recentMatches(){return `<table class="table"><thead><tr><th>Wedstrijd</th><th>Score</th><th>Status</th></tr></thead><tbody>${db.matches.slice(0,4).map(m=>`<tr class="row-click" data-action="open-match" data-id="${m.id}" tabindex="0"><td><div class="name-cell">${avatar(m.players[0],'sm')}<div><strong>${esc(short(m.players[0]))} vs ${esc(short(m.players[1]))}</strong><small>Bord ${m.board} · ${esc(m.mode)}</small></div></div></td><td class="score">${m.legs.join(' – ')}</td><td>${liveBadge(m)}</td></tr>`).join('')}</tbody></table>`;}
function totals(p){let s={...p};for(const m of db.matches){const rm=db.play?.rooms?.[m.id];if(rm&&(rm.type==='practice'||rm.phase==='lobby'||!rm.confirmations?.every(Boolean)))continue;let i=m.players.indexOf(p.id);if(i<0)continue;s.oneEighties+=m.stats[i].oneEighties;s.finish=Math.max(s.finish,m.stats[i].highestFinish);if(m.status==='finished'){s.played++;if(m.winner===p.id)s.won++;}}return s;}
function ranked(){return db.players.filter(p=>p.status==='approved').map(totals).sort((a,b)=>b[rankMetric]-a[rankMetric]);}
function rankingPanel(){let r=ranked(),label=rankMetric==='finish'?'hoogste finish':rankMetric==='avg'?'gemiddelde':"180’ers";return `<section class="panel ranking-panel"><div class="section-heading"><h2>De koplopers</h2>${badge('SEIZOEN 2026')}</div><span class="subtle-label">Meeste 180’ers · clubseizoen</span><div class="podium">${[1,0,2].map((idx,i)=>{let p=r[idx];return `<div class="podium-person ${['second','first','third'][i]}">${idx===0?`<div class="crown">${icon('crown')}</div>`:''}${avatar(p.id)}<span class="podium-name">${esc(short(p.id))}</span><span class="podium-stat">${p[rankMetric]}</span><small>${label}</small><div class="podium-step">${idx+1}</div></div>`;}).join('')}</div><div class="ranking-list">${r.slice(3,6).map((p,i)=>`<div class="ranking-row"><div class="who"><span class="rank-num">0${i+4}</span>${avatar(p.id,'sm')}<span>${esc(p.name)}</span></div><b>${p[rankMetric]}</b></div>`).join('')}</div>${button('Volledige ranglijst '+icon('arrow'),'nav','ghost block','data-to="rankings"')}</section>`;}
function dashboard(){rankMetric='oneEighties';return `<section class="brand-hero"><div class="brand-hero-copy">`+header(`Jouw volgende leg.<br><em>Jouw volgende niveau.</em>`,`${admin()?'Welkom terug, Danny.':'Welkom, Rick.'} Dit speelt er bij De Puinruimers.`,`<span class="date-label">Woensdag 4 november 2026</span>${button(icon('plus')+' Nieuw toernooi','new-tour','gold',admin()?'':'disabled')}`)+`</div><img class="brand-hero-emblem" src="assets/dartflow-icon.svg" alt="Dartflow Royal Oche schild"></section><div class="metrics">${metric('Actieve toernooien',db.tournaments.filter(t=>['active','open'].includes(t.status)).length,'trophy','<b>01</b> inschrijving open')}${metric('Spelers bij de club',db.players.filter(p=>p.status==='approved').length,'users','<b>+3</b> deze maand')}${metric('Dartborden in gebruik',`${db.matches.filter(m=>m.status==='live').length}<span style="font-size:17px;color:#8f8370"> / 4</span>`,'target','<b>●</b> De club is aan zet')}${metric('Gespeelde legs',156+db.matches.reduce((a,m)=>a+m.visits.filter(v=>v.checkout).length,0),'chart','',true)}</div><div class="dashboard-grid"><div class="dash-main">${sectionHeading('Live aan de oche','Alle wedstrijden','nav-matches',`<span class="live-caption"><i class="live-dot"></i>${db.matches.filter(m=>m.status==='live').length} borden live</span>`)}<div class="live-boards">${db.matches.slice(0,4).map(boardCard).join('')}</div><div class="dashboard-lower"><section>${sectionHeading('De toernooien','Bekijk alle','nav-tournaments')}${db.tournaments.filter(t=>t.status==='active'||t.status==='open').slice(0,2).map(compactTour).join('')}</section><section class="panel matches-panel">${sectionHeading('Laatste wedstrijden','Alles','nav-matches')}${recentMatches()}<div class="mini-activity">${icon('clock')} ${db.activity[0]?esc(db.activity[0]):'De scoreborden staan klaar. Wie gooit de volgende 180?'}</div></section></div></div><aside class="dash-side">${rankingPanel()}<section class="panel quick-panel"><h2>Snel geregeld</h2>${[[admin()?'Nieuw toernooi aanmaken':'Toernooien ontdekken','trophy',admin()?'new-tour':'nav-tournaments'],['Spelers bekijken','users','nav-players'],[admin()?'Aanmeldingen beoordelen':'Mijn aanmeldingen','clipboard','nav-registrations']].map(([l,i,a])=>`<button class="quick-btn" data-action="${a}">${icon(i)}${l}${icon('right','end')}</button>`).join('')}</section><section class="next-event"><div class="eyebrow">De volgende afspraak</div><h3>Vrijdagavond Masters</h3><p>6 november · 19:30 uur · Clubhuis</p>${button('Bekijk toernooi '+icon('right'),'tour-detail','small ghost','data-id="2"')}${icon('trophy')}</section></aside></div>`;}
function tournaments(){const f=db.tournaments.filter(t=>inScope(t)&&(tourFilter==='all'||t.status===tourFilter));return header('Elk toernooi. <em>Alles geregeld.</em>','Van de eerste inschrijving tot de laatste dubbel.',admin()?button(icon('plus')+' Nieuw toernooi','new-tour','gold'):button(icon('user')+' Speler aanmelden','register','gold'))+`<div class="toolbar"><div class="tabs">${[['all','Alle toernooien'],['active','Actief'],['open','Inschrijving open'],['draft','In planning'],['finished','Afgelopen']].map(([id,l])=>`<button class="tab ${tourFilter===id?'active':''}" data-action="tour-filter" data-value="${id}">${l}</button>`).join('')}</div><span class="subtle-label">${f.length} toernooien</span></div><div class="tour-grid">${f.map(t=>`<article class="panel tour-card"><div class="tour-cover">${icon('trophy')}<span class="tour-num">${String(db.tournaments.indexOf(t)+1).padStart(2,'0')}</span></div><div class="tour-card-content">${tourStatus(t)}<h3>${esc(t.name)}</h3><div class="tour-facts"><span>${icon('calendar')}${date(t.date)}</span><span>${icon('users')}${t.players}/${t.capacity} spelers</span><span>${icon('bracket')}${esc(t.format)}</span><span>${icon('target')}${t.score} · Dubbel uit</span><span>${icon('pin')}${esc(t.location)}</span><span>${icon('target')}Best of ${t.bestOf}</span></div><div class="progress-label"><span>${t.status==='open'?'Inschrijvingen':'Toernooivoortgang'}</span><span>${t.status==='open'?Math.round(t.players/t.capacity*100):t.progress}%</span></div><div class="progress"><span style="width:${t.status==='open'?t.players/t.capacity*100:t.progress}%"></span></div><div class="tour-card-actions">${button('Bekijk toernooi '+icon('right'),'tour-detail','gold small',`data-id="${t.id}"`)}${admin()?button(icon('edit')+' Wijzig','edit-tour','ghost small',`data-id="${t.id}"`):t.status==='open'?button('Deelnemen','join-tour','small',`data-id="${t.id}"`):''}</div></div></article>`).join('')}</div>`;}
function players(){return header('De spelers. <em>De smaakmakers.</em>','Alle spelers, hun vorm en hun beste worpen.',button(icon('plus')+(admin()?' Speler toevoegen':' Speler aanmelden'),admin()?'new-player':'register','gold'))+`<div class="toolbar"><div class="input-wrap">${icon('search')}<input class="input" id="player-search" aria-label="Zoek een speler" placeholder="Zoek op naam of e-mailadres…" value="${esc(playerSearch)}"></div><span class="subtle-label">${db.players.filter(p=>p.status==='approved').length} goedgekeurde spelers</span></div><div class="panel full-table"><table class="table"><thead><tr><th>Speler</th><th>Wedstrijden</th><th>Gewonnen</th><th>Gemiddelde</th><th>180’ers</th><th>Hoogste finish</th><th></th></tr></thead><tbody>${db.players.filter(p=>p.status==='approved').map(totals).map(p=>`<tr data-search="${esc((p.name+' '+p.email).toLowerCase())}" ${playerSearch&&!`${p.name} ${p.email}`.toLowerCase().includes(playerSearch.toLowerCase())?'hidden':''}><td><div class="name-cell">${avatar(p.id)}<div><strong>${esc(p.name)}</strong><small>${esc(p.email)}</small></div></div></td><td>${p.played}</td><td>${p.won}</td><td class="stat-gold">${p.avg.toFixed(1)}</td><td>${p.oneEighties}</td><td>${p.finish}</td><td>${button('Profiel '+icon('right'),'player-profile','ghost small',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table><p class="subtle-label" id="search-empty" hidden style="padding:20px">Geen spelers gevonden.</p></div>`;}
function registrations(){let items=scopedRegistrationRequests().filter(r=>(requestFilter==='all'||r.status===requestFilter)&&(admin()||r.playerId===1||r.email==='rick@voorbeeld.test'));return header('Een plek <em>aan de oche.</em>',admin()?'Beoordeel nieuwe clubspelers en deelnameverzoeken.':'Bekijk je deelnameverzoeken en meld je aan.',button(icon('plus')+' Aanmelding maken','register','gold'))+`<div class="notice">${icon('info')}Demomodus: aanmeldingen en goedkeuringen worden lokaal opgeslagen. Er worden geen e-mails verzonden.</div><div class="tabs">${[['pending','Te beoordelen'],['approved','Goedgekeurd'],['rejected','Afgewezen'],['all','Alle aanmeldingen']].map(([id,l])=>`<button class="tab ${requestFilter===id?'active':''}" data-action="request-filter" data-value="${id}">${l}${id==='pending'&&admin()?` (${pending()})`:''}</button>`).join('')}</div><div class="request-grid">${items.map(r=>`<article class="panel request-card"><div class="who">${avatar(r.name)}<div><h3>${esc(r.name)}</h3><p>${esc(r.email)}</p></div></div><div style="display:flex;justify-content:space-between">${badge(r.type==='player'?'Nieuwe clubspeler':'Toernooi-inschrijving',r.type==='player'?'blue':'pending')}<span class="subtle-label">${esc(r.date)}</span></div><div class="request-info">${r.type==='player'?'Wil zich aansluiten bij De Puinruimers.':`Wil meedoen aan <b>${esc(T(r.tournament).name)}</b>.`}</div>${r.status==='pending'&&admin()?`<div class="request-actions">${button(icon('check')+' Goedkeuren','approve-request','green small',`data-id="${r.id}"`)}${button(icon('close')+' Afwijzen','reject-request','ghost small',`data-id="${r.id}"`)}</div>`:badge({pending:'Wacht op goedkeuring',approved:'Goedgekeurd',rejected:'Afgewezen'}[r.status],r.status)}</article>`).join('')}</div>${!items.length?empty('Alles bijgewerkt','Er zijn geen aanmeldingen in deze categorie.','clipboard'):''}`;}
function tourSelect(){return `<select class="input" id="selected-tour" aria-label="Selecteer toernooi">${db.tournaments.filter(t=>t.format==='Poules + knock-out').map(t=>`<option value="${t.id}" ${selectedTour===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`;}
function pools(embedded=false){const t=T(selectedTour);return (embedded?'':header('De poules. <em>De eerste stap.</em>','Iedereen speelt. De beste twee gaan door naar de knock-out.',admin()?button(icon('shuffle')+' Opnieuw indelen','shuffle-pools','gold',selectedTour!==1?'disabled':''):button(icon('trophy')+' Toernooien','nav-hall','ghost')))+`<div class="toolbar">${embedded?`<strong class="subtle-label">Poules van ${esc(t.name)}</strong>${admin()?button(icon('shuffle')+' Opnieuw indelen','shuffle-pools','small ghost',selectedTour!==1?'disabled':''):''}`:tourSelect()}<span class="subtle-label">${selectedTour===1?db.pools.length:'0'} poules · Top 2 gaan door</span></div>${selectedTour!==1?empty('Nog geen deelnemers','Keur eerst spelers goed voor dit toernooi. De demo-indeling hoort bij Puinruimers Open.','users'):`<div class="pools-grid">${db.pools.map((ids,idx)=>{let rows=ids.map((id,i)=>{let played=2,won=[2,1,1,0][i],lf=[6,4,3,1][i],la=[1,3,4,6][i];db.matches.filter(m=>m.status==='finished'&&m.players.includes(id)&&ids.includes(m.players[0])&&ids.includes(m.players[1])).forEach(m=>{played++;won+=m.winner===id?1:0;const ix=m.players.indexOf(id);lf+=m.legs[ix];la+=m.legs[1-ix];});return{id,played,won,lf,la};}).sort((a,b)=>b.won-a.won||(b.lf-b.la)-(a.lf-a.la));return `<section class="panel pool"><div class="pool-head"><h3>Poule ${String.fromCharCode(65+idx)}</h3>${badge('501 · Best of 5')}</div><table class="table"><thead><tr><th>Speler</th><th>G</th><th>W</th><th>Legs</th><th>Pnt</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i<2?'qualification':''}"><td><div class="name-cell"><span class="subtle-label">${i+1}</span>${avatar(r.id,'sm')}<strong>${esc(P(r.id).name)}</strong></div></td><td>${r.played}</td><td>${r.won}</td><td>${r.lf}–${r.la}</td><td class="stat-gold">${r.won*2}</td></tr>`).join('')}</tbody></table><div class="pool-key"><span></span>Top 2 naar de knock-out · Voorbeeldstand</div></section>`;}).join('')}</div>`}`;}
function knockout(){const round=db.knockout.findIndex(r=>r.some(m=>!m.winner));return header('Op weg naar <em>de finale.</em>','Eén schema. Acht kanshebbers. Eén winnaar.',admin()&&round>=0?button(icon('bolt')+' Simuleer '+['kwartfinales','halve finales','finale'][round],'advance-bracket','gold'):round<0?badge(`${P(db.knockout[2][0].winner).name} wint!`,'approved'):'')+`<div class="notice">${icon('info')}Interactief knock-outvoorbeeld · Gebruik ‘Simuleer’ om uitslagen in te vullen en winnaars door te laten gaan.</div><div class="panel bracket-container"><div class="bracket-scroll"><div class="bracket">${db.knockout.map((r,i)=>`<div class="bracket-col ${i===2?'final':''}"><h3>${['Kwartfinale','Halve finale','Finale'][i]} ${i===2?'· '+(db.knockout[2][0].winner?'🏆':'Best of 7'):'· Best of 5'}</h3>${r.map((m,j)=>`<article class="bracket-match">${m.players.map((id,k)=>`<div class="bracket-player ${m.winner===id&&id?'winner':''} ${!id?'tbd':''}">${id?avatar(id,'sm'):icon('user')}<span>${id?esc(P(id).name):'Winnaar vorige ronde'}</span><b>${m.score?m.score[k]:'–'}</b></div>`).join('')}<small>${m.winner?'Afgelopen':m.players.every(Boolean)?'Ingepland · bord '+(j+1):'Wacht op uitslag'}</small></article>`).join('')}</div>`).join('')}</div></div></div>${admin()?`<div style="margin-top:18px">${button(icon('undo')+' Schema herstellen','reset-bracket','ghost small')}</div>`:''}`;}
function matches(){return header('Elke worp <em>in beeld.</em>','Volg de vier borden of stap zelf achter het scorebord.',button(icon('download')+' Uitslagen exporteren','export-matches','ghost'))+`<div class="live-boards">${db.matches.map(boardCard).join('')}</div><section class="panel">${sectionHeading('Het wedstrijdprogramma','','')}${recentMatches()}</section><div class="notice" style="margin-top:20px">${icon('info')}Online en hybride zijn voorbeeldlabels. Camera en externe verbindingen zijn in dit prototype niet gekoppeld.</div>`;}
function rankings(){const r=ranked();return header('Mooie worpen. <em>Grote namen.</em>','De clubranglijst voor seizoen 2026. Voorbeelddata + jouw demoprestaties.',button(icon('download')+' Ranglijst exporteren','export-ranking','ghost'))+`<div class="metrics">${metric('Meeste 180’ers',r.reduce((a,p)=>Math.max(a,p.oneEighties),0),'target','<b>SEIZOEN</b> 2026')}${metric('Hoogste finish',Math.max(...r.map(p=>p.finish)),'bolt','<b>DUBBEL UIT</b> record')}${metric('Beste gemiddelde',Math.max(...r.map(p=>p.avg)).toFixed(1),'chart','<b>3 DARTS</b> gemiddelde')}${metric('Spelers in de ranking',r.length,'users','<b>ALLE</b> clubspelers')}</div><div class="tabs">${[['oneEighties','Meeste 180’ers'],['finish','Hoogste finish'],['avg','Hoogste gemiddelde'],['won','Meeste overwinningen']].map(([id,l])=>`<button class="tab ${rankMetric===id?'active':''}" data-action="rank-filter" data-value="${id}">${l}</button>`).join('')}</div><div class="panel full-table"><table class="table"><thead><tr><th>Positie</th><th>Speler</th><th>Gewonnen</th><th>Gemiddelde</th><th>180’ers</th><th>Hoogste finish</th><th></th></tr></thead><tbody>${r.map((p,i)=>`<tr><td style="color:${i<3?'#e9c575':'#9b8d77'}">${i<3?icon(i===0?'crown':'trophy'):String(i+1).padStart(2,'0')}</td><td><div class="name-cell">${avatar(p.id)}<strong>${esc(p.name)}</strong></div></td><td>${p.won}</td><td class="${rankMetric==='avg'?'stat-gold':''}">${p.avg.toFixed(1)}</td><td class="${rankMetric==='oneEighties'?'stat-gold':''}">${p.oneEighties}</td><td class="${rankMetric==='finish'?'stat-gold':''}">${p.finish}</td><td>${button('Profiel','player-profile','small ghost',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
function statistics(){return header('De vorm <em>van de club.</em>','Zo ontwikkelt het seizoen zich. Alle grafieken bevatten voorbeelddata.')+`<div class="metrics">${metric('Clubgemiddelde','68.7','chart','<b>↗ 4.2</b> vs vorige maand')}${metric('Gegooide 180’ers','94','target','<b>+18</b> deze maand')}${metric('Checkoutpercentage','32.8%','bolt','<b>↗ 2.4%</b> deze maand')}${metric('Gespeelde wedstrijden','86','trophy','<b>12</b> deze week')}</div><div class="chart-grid"><section class="panel chart-panel"><h2>Het niveau blijft stijgen.</h2><p>Gemiddelde per 3 darts · laatste zes speelavonden</p><svg class="chart-svg" role="img" aria-label="Clubgemiddelde stijgt van 59 naar 69 tussen september en november" viewBox="0 0 600 270"><defs><linearGradient id="chart-fill" x2="0" y2="1"><stop stop-color="#c6a759" stop-opacity=".25"/><stop offset="1" stop-color="#c6a759" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="35" x2="585" y1="${30+i*60}" y2="${30+i*60}" stroke="#34412b" stroke-dasharray="3 5"/><text x="5" y="${34+i*60}" fill="#7d906b" font-size="10">${80-i*10}</text>`).join('')}<path d="M40 158 145 139 250 146 355 105 460 93 575 74V215H40Z" fill="url(#chart-fill)"/><path d="M40 158 145 139 250 146 355 105 460 93 575 74" fill="none" stroke="#dabc72" stroke-width="3" stroke-linejoin="round"/><path d="M40 193 145 178 250 184 355 164 460 142 575 137" fill="none" stroke="#809a68" stroke-width="2" stroke-dasharray="5 4"/>${[[40,158],[145,139],[250,146],[355,105],[460,93],[575,74]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#dfc17a" stroke="#1e2a16" stroke-width="3"/><text x="${x}" y="245" text-anchor="middle" fill="#7d906b" font-size="9">${['25 sep','2 okt','9 okt','16 okt','23 okt','4 nov'][i]}</text>`).join('')}</svg><div class="chart-legend"><span>Dit seizoen</span><span>Vorig seizoen</span></div></section><section class="panel chart-panel"><h2>De scorende handen.</h2><p>180’ers per speler · top 6</p>${db.players.slice(0,8).sort((a,b)=>b.oneEighties-a.oneEighties).slice(0,6).map(p=>`<div class="stats-bar"><label>${esc(short(p.id))}</label><div class="progress"><span style="width:${p.oneEighties/18*100}%"></span></div><b>${p.oneEighties}</b></div>`).join('')}<div class="notice" style="margin-top:25px;margin-bottom:0">${icon('info')}Seizoencijfers zijn mock-data. Nieuwe scores vind je bij de wedstrijdstatistieken.</div></section></div>`;}
function settings(){const s=db.settings;return header('Jouw club. <em>Jouw spelregels.</em>','Stel de club, standaardwedstrijden en jouw demo-ervaring in.')+`<div class="settings-grid"><form class="panel" data-form="settings"><h2>Club & wedstrijden</h2><label class="field">Clubnaam<input class="input" name="club" maxlength="60" required value="${esc(s.club)}" ${!admin()?'disabled':''}></label><div class="field-row"><label class="field">Plaats<input class="input" name="location" maxlength="60" value="${esc(s.location)}" ${!admin()?'disabled':''}></label><label class="field">Contact e-mail<input class="input" type="email" name="email" required value="${esc(s.email)}" ${!admin()?'disabled':''}></label></div><div class="field-row"><label class="field">Standaardspel<select name="score" ${!admin()?'disabled':''}><option ${s.score===501?'selected':''}>501</option><option ${s.score===301?'selected':''}>301</option></select></label><label class="field">Best of<select name="bestOf" ${!admin()?'disabled':''}>${[3,5,7,9].map(x=>`<option value="${x}" ${s.bestOf===x?'selected':''}>${x} legs</option>`).join('')}</select></label></div><div class="notice">${icon('info')}De standaardspelregels worden gebruikt bij nieuwe toernooien.</div><button class="btn gold" ${!admin()?'disabled':''}>${icon('check')} Instellingen opslaan</button></form><div><section class="panel"><h2>Jouw demo-ervaring</h2><div class="toggle-row"><div><strong>Demo-meldingen</strong><small>Toon voorbeeldmeldingen in het overzicht.</small></div><button class="switch ${s.notifications?'on':''}" role="switch" aria-checked="${s.notifications}" aria-label="Demo-meldingen" data-action="toggle-setting" data-key="notifications"></button></div><div class="toggle-row"><div><strong>Beweging & animaties</strong><small>Subtiele overgangen in de app.</small></div><button class="switch ${s.motion?'on':''}" role="switch" aria-checked="${s.motion}" aria-label="Beweging en animaties" data-action="toggle-setting" data-key="motion"></button></div><div class="toggle-row" style="border-bottom:0"><div><strong>Actieve demorol</strong><small>${admin()?'Beheerder · Danny':'Speler · Rick'}</small></div>${button('Wisselen','role','small ghost')}</div></section><section class="panel" style="margin-top:18px"><h2>Een frisse start</h2><p class="subtle-label">Herstel alle spelers, toernooien, verzoeken en scores naar de oorspronkelijke voorbeelddata.</p>${button(icon('undo')+' Demogegevens herstellen','reset-demo','danger small')}</section></div></div>`;}
function empty(title,sub,ic='info'){return `<div class="panel empty">${icon(ic)}<h3>${title}</h3><p>${sub}</p></div>`;}
function matchView(){const m=db.matches.find(m=>m.id===matchId)||db.matches[0];const i=m.turn,pl=m.players[i],suggestion=checkout(m.remaining[i]);const avg=k=>m.stats[k].darts?(m.stats[k].total/m.stats[k].darts*3).toFixed(1):P(m.players[k]).avg.toFixed(1);return header(`Bord ${m.board}. <em>${m.status==='live'?'Aan de oche.':'De laatste dubbel.'}</em>`,`${T(m.tournament).name} · ${m.mode}${m.mode!=='Op locatie'?' (demo)':''}`,button(icon('left')+' Alle wedstrijden','nav-matches','ghost'))+`<div class="match-layout"><section class="panel scoreboard"><div class="match-meta">${liveBadge(m)}<span>${m.startScore} · Dubbel uit · Best of ${m.bestOf}</span></div><div class="match-title">${m.status==='live'?'ELKE WORP TELT. ELKE LEG OPNIEUW.':'WEDSTRIJD AFGEROND'}</div><div class="score-players">${m.players.map((p,k)=>`${k===1?'<div class="score-divider">vs</div>':''}<div class="score-player ${i===k&&m.status==='live'?'turn':''}">${avatar(p)}<h3>${esc(short(p))}</h3><span class="remaining">${m.remaining[k]}</span><small>RESTEREND</small></div>`).join('')}</div><div class="leg-score">${m.legs[0]} – ${m.legs[1]}<small>LEGS</small></div>${m.status==='finished'?`<div class="finished-state">${icon('trophy')}<h2>${esc(P(m.winner).name)} wint!</h2><p class="subtle-label">De uitslag is opgeslagen in deze demo.</p></div>`:`<div class="turn-label"><i class="live-dot"></i>${esc(short(pl))} is aan de beurt</div><div class="checkout"><small>${suggestion?'Finishsuggestie':'Op weg naar de dubbel'}</small>${suggestion||'Speel jezelf naar een finish.'}</div><div class="score-input"><label for="score-value">Score van<br>de beurt</label><input id="score-value" aria-label="Beurtscore van 0 tot 180" value="${scoreText}" inputmode="numeric" pattern="[0-9]*" maxlength="3" autocomplete="off"><label>Darts<select id="darts-count" aria-label="Aantal gegooide darts"><option value="3">3 darts</option><option value="2">2 darts</option><option value="1">1 dart</option></select></label></div><div class="keypad">${['1','2','3','4','5','6','7','8','9','back','0','ok'].map(k=>`<button data-action="key" data-key="${k}" class="${k==='ok'?'confirm':''}" aria-label="${k==='back'?'Wis laatste cijfer':k==='ok'?'Score bevestigen':k}">${k==='back'?icon('backspace'):k==='ok'?'OK':k}</button>`).join('')}</div><div class="quick-scores">${[26,60,100,180].map(s=>`<button data-action="quick-score" data-value="${s}">${s}</button>`).join('')}</div><div id="score-error" class="inline-error" role="alert"></div>`}<div class="match-bottom">${button(icon('undo')+' Laatste beurt terug','undo-score','ghost small',m.history.length?'':'disabled')}${button(icon('info')+' Spelregels','score-rules','ghost small')}</div></section><aside class="match-side"><section class="panel"><h2>Het verhaal in cijfers</h2><div class="stat-compare"><b>${esc(short(m.players[0]))}</b><span>Wedstrijdstatistieken</span><b>${esc(short(m.players[1]))}</b></div>${[['3-darts gemiddelde',avg(0),avg(1)],['180’ers',m.stats[0].oneEighties,m.stats[1].oneEighties],['Hoogste finish',m.stats[0].highestFinish||'–',m.stats[1].highestFinish||'–'],['Gegooide darts',m.stats[0].darts,m.stats[1].darts]].map(([l,a,b])=>`<div class="stat-compare"><b>${a}</b><span>${l}</span><b>${b}</b></div>`).join('')}<p class="subtle-label" style="font-size:8px;margin-bottom:0">Gemiddelde start met voorbeelddata; na je eerste beurt gebruiken we jouw invoer.</p></section><section class="panel"><h2>Beurt voor beurt</h2><div class="turn-history">${m.visits.length?m.visits.slice().reverse().map((v,k)=>`<div class="turn-row"><small>${m.visits.length-k}</small><span>${esc(short(m.players[v.playerIndex]))}${v.bust?' · Bust':v.checkout?' · Leg!':''}</span><b>${v.score}</b><span>${v.remainingAfter}</span></div>`).join(''):`<p class="subtle-label">De voorbeeldwedstrijd is al onderweg.<br>Jouw nieuwe beurten verschijnen hier.</p>`}</div></section>${m.mode!=='Op locatie'?`<div class="notice">${icon('wifi')}Voorbeeld van ${m.mode.toLowerCase()} spelen. Er is geen camera of liveverbinding actief.</div>`:''}</aside></div>`;}
function activeClub(){return db.play?.clubs?.items?.find(cl=>String(cl.id)===String(db.play?.activeClubId))||null;}
function scopeId(){return activeClub()?.id||null;}
function scopeName(){return activeClub()?.name||'Dartflow Wereldwijd';}
function inScope(item){return String(item.clubId??'global')===String(scopeId()??'global');}
function switchScope(value,playNow=false){
  const club=value==='global'?null:db.play.clubs.items.find(item=>String(item.id)===String(value)&&item.members.some(m=>Number(m.id)===1));
  if(value!=='global'&&!club){render();toast('Word eerst lid van deze vereniging.');return;}
  db.play.activeClubId=club?.id??null;
  save();
  go(playNow?'practice':routeAfterScopeChange(route,db.play.space==='organizer'));
}
function scopeOptions(){
  return `<option value="global" ${!activeClub()?'selected':''}>Dartflow Wereldwijd</option>`+(db.play.clubs?.items||[])
    .filter(cl=>cl.members.some(m=>Number(m.id)===1)).map(cl=>`<option value="${cl.id}" ${activeClub()?.id===cl.id?'selected':''}>${esc(cl.name)}</option>`).join('');
}
function searchResults(query=''){
  const term=query.toLowerCase().trim();
  const views=navigationSearch(db.play.space==='organizer').filter(([, ,label])=>label.toLowerCase().includes(term));
  const pages=views.slice(0,term?9:6).map(([id,glyph,label])=>`<button class="search-result" data-action="nav" data-to="${id}">${icon(glyph)}${esc(label)}<small>Scherm</small></button>`);
  if(!term) return pages.join('');
  const club=activeClub();
  const people=db.players.filter(player=>(!club||club.members.some(member=>member.id===player.id))&&player.name.toLowerCase().includes(term)).slice(0,4)
    .map(player=>`<button class="search-result" data-action="player-profile" data-id="${player.id}">${avatar(player.id,'sm')}${esc(player.name)}<small>Speler</small></button>`);
  const events=db.tournaments.filter(t=>inScope(t)&&t.name.toLowerCase().includes(term)).slice(0,4)
    .map(t=>`<button class="search-result" data-action="open-scoped-tournament" data-id="${t.id}">${icon('trophy')}${esc(t.name)}<small>Toernooi</small></button>`);
  return [...pages,...people,...events].join('')||'<p class="subtle-label">Geen resultaten in deze omgeving.</p>';
}
function updateMenuAccessibility(){
  const sidebar=document.getElementById('df-sidebar');
  if(!sidebar) return;
  sidebar.inert=mobileViewport.matches&&!navOpen;
  document.querySelector('.df-main').inert=mobileViewport.matches&&navOpen;
  document.querySelectorAll('[aria-controls="df-sidebar"]').forEach(toggle=>toggle.setAttribute('aria-expanded',String(navOpen)));
  document.getElementById('df-menu-toggle')?.setAttribute('aria-label',navOpen?'Menu sluiten':'Menu openen');
}
function setMenu(open){
  if(!document.getElementById('df-sidebar')) return;
  navOpen=open&&mobileViewport.matches;
  document.querySelector('.sidebar')?.classList.toggle('open',navOpen);
  document.querySelector('.mobile-shade')?.classList.toggle('visible',navOpen);
  document.querySelector('.df-bottom [data-action="toggle-menu"]')?.classList.toggle('active',navOpen);
  updateMenuAccessibility();
  const focus=navOpen?document.querySelector('.df-menu-close'):document.getElementById('df-menu-toggle');
  focus?.focus({preventScroll:true});
}
mobileViewport.addEventListener('change',()=>{
  if(!mobileViewport.matches&&navOpen) setMenu(false);
  else updateMenuAccessibility();
});
function practiceView(train=false){return `<div class="tabs"><button class="tab ${!train?'active':''}" data-action="nav" data-to="practice">Oefenwedstrijd spelen</button><button class="tab ${train?'active':''}" data-action="nav" data-to="training">Solo & training</button></div>`+(train?training.view():rooms.lobby());}
function render(){
 if(!portal)return;portal.init();community.init();clubs.init();venue.init();
 baan.setRoute(route,pageParam);
 document.body.classList.toggle('no-motion',!db.settings.motion);
 const fullVenueDisplay = route === 'venue-cast' && pageParam.split('?')[0] !== 'studio';
 document.body.classList.toggle('vf-display-mode', fullVenueDisplay);
 document.body.classList.toggle('vf-obs-mode', fullVenueDisplay && pageParam.split('?')[0] === 'obs');
 document.body.classList.toggle('dr-overlay-mode',route==='overlay');
 const fullBaanDisplay = route === 'baan-screen' || route === 'baan-phone';
 document.body.classList.toggle('bf-standalone', fullBaanDisplay);
 if(fullBaanDisplay){document.getElementById('app').innerHTML=baan.view();return;}
 if(fullVenueDisplay){document.getElementById('app').innerHTML=venueCast.view();return;}
 if(route==='overlay'){document.getElementById('app').innerHTML=portal.overlay();return;}
 const organizer=db.play.space==='organizer';
 const current=organizer&&route==='home'?'dashboard':!organizer&&route==='dashboard'?'home':route;
 const views={
   home:()=>portal.home(),play:()=>renderPlayHub(ctx),practice:()=>practiceView(false),
   lobby:()=>practiceView(false),training:()=>practiceView(true),clubs:()=>clubs.view(),
   mymatches:()=>portal.mymatches(),events:()=>renderEventsHub(ctx),leagues:()=>competitions.leagues(),
   hall:()=>competitions.hall(),operations:()=>renderOperations(ctx),baan:()=>baan.view(),
   venue:()=>venue.view(),'venue-cast':()=>venueCast.view(),manage:()=>renderManageHub(ctx),
   friends:()=>portal.friends(),community:()=>community.view(),reports:()=>portal.reports(),
   camera:()=>rooms.camera(),match:()=>rooms.room(),spectator:()=>rooms.room(true),
   dashboard:()=>organizer?renderOrganizerDashboard(ctx):portal.home(),
   tournaments,players,registrations,pools,knockout,matches,rankings,statistics,
   settings:()=>portal.preferences()
 };
 const requests=db.play.social?.requests||[];
 const venueOptions=ctx.scopedVenueEvents();
 const scopeVenue=venueOptions.find(event=>event.id===db.venue?.id&&(['venue','venue-cast'].includes(route)||event.stage!=='finished'))
   ||venueOptions.find(event=>event.stage!=='finished')||venueOptions[0];
 document.getElementById('app').innerHTML=renderShell({
   route:current,organizer,navOpen,page:(views[current]||views[organizer?'dashboard':'home'])(),
   icon,esc,scopeOptions:scopeOptions(),isClub:Boolean(activeClub()),avatar,
   notify:db.settings.notifications&&(organizer?pending()>0:requests.some(r=>r.status==='pending'&&r.to===1)),
   dark:['match','spectator'].includes(route),venueId:scopeVenue?.id
 });
 updateMenuAccessibility();
 rooms.afterRender?.();
}
function showModal(title,sub,body,wide=false){modalOrigin=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-top"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Sluiten">${icon('close')}</button></div>${sub?`<p>${sub}</p>`:''}${body}</section></div>`;requestAnimationFrame(()=>{const el=document.querySelector('.modal input:not([type=hidden]),.modal select,.modal');el?.focus();});}
function closeModal(){document.getElementById('modal-root').innerHTML='';modalOrigin?.isConnected&&modalOrigin.focus();}
function tourForm(id){if(!admin())return;const t=id?T(id):{name:'',date:'2026-11-13',format:'Poules + knock-out',capacity:32,status:'draft',score:db.settings.score,bestOf:db.settings.bestOf,location:activeClub()?.name||'Dartflow Wereldwijd'};showModal(id?'Toernooi wijzigen':'Een nieuw toernooi.','Zet het podium klaar voor de volgende clubavond.',`<form data-form="tournament"><input type="hidden" name="id" value="${id||''}"><label class="field">Toernooinaam<input class="input" name="name" maxlength="65" required placeholder="Bijv. Vrijdagavond Open" value="${esc(t.name)}"></label><div class="field-row"><label class="field">Datum<input class="input" name="date" type="date" required value="${t.date}"></label><label class="field">Maximaal spelers<select name="capacity">${[8,16,24,32,64].map(x=>`<option ${t.capacity===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field">Locatie<input class="input" name="location" maxlength="80" required value="${esc(t.location)}"></label><div class="field-row"><label class="field">Format<select name="format"><option ${t.format==='Poules + knock-out'?'selected':''}>Poules + knock-out</option><option ${t.format==='Knock-out'?'selected':''}>Knock-out</option></select></label><label class="field">Status<select name="status">${[['draft','In planning'],['open','Inschrijving open'],['active','Actief'],['finished','Afgelopen']].map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="field-row"><label class="field">Spel<select name="score"><option ${t.score===501?'selected':''}>501</option><option ${t.score===301?'selected':''}>301</option></select></label><label class="field">Best of<select name="bestOf">${[3,5,7,9].map(x=>`<option value="${x}" ${t.bestOf===x?'selected':''}>${x} legs</option>`).join('')}</select></label></div><div class="inline-error" id="form-error"></div><div class="modal-actions">${button('Annuleren','close-modal','ghost')}<button class="btn gold">${icon('check')} ${id?'Wijzigingen opslaan':'Toernooi aanmaken'}</button></div></form>`);}
function tourDetail(id){const t=T(id);showModal(esc(t.name),`${date(t.date)} · ${esc(t.location)}`,`<div class="modal-meta">${tourStatus(t)}${badge(t.format)}${badge(`${t.score} · Dubbel uit`)}</div><div class="profile-stats"><div><b>${t.players}</b><small>DEELNEMERS</small></div><div><b>${t.capacity}</b><small>PLAATSEN</small></div><div><b>${t.bestOf}</b><small>BEST OF LEGS</small></div></div><div class="notice">${icon('info')}${t.id===1?'De poulefase is onderweg. Volg de wedstrijden en bekijk de voorbeeldstand.':t.status==='open'?`${t.capacity-t.players} plaatsen beschikbaar. Aanmeldingen worden door de beheerder beoordeeld.`:t.status==='finished'?'Dit voorbeeldtoernooi is afgerond.':'Het toernooi wordt voorbereid. Inschrijven kan zodra de inschrijving opent.'}</div><div class="modal-actions">${admin()?button(icon('edit')+' Wijzigen','edit-tour','ghost',`data-id="${t.id}"`):''}${t.status==='open'?button('Meld mij aan '+icon('arrow'),'join-tour','gold',`data-id="${t.id}"`):t.id===1?button('Bekijk poules '+icon('arrow'),'tour-pools','gold',`data-id="${t.id}"`):button('Sluiten','close-modal','gold')}</div>`);}
function registerForm(direct=false){showModal(direct?'Voeg een clubspeler toe.':'Schuif aan bij de club.',direct?'De speler is na toevoegen direct goedgekeurd.':'Je aanmelding komt bij de beheerder terecht. Dit is een lokale demo.',`<form data-form="player"><input type="hidden" name="direct" value="${direct}"><label class="field">Volledige naam<input class="input" name="name" maxlength="60" required placeholder="Voor- en achternaam"></label><label class="field">E-mailadres<input class="input" name="email" type="email" maxlength="100" required placeholder="naam@voorbeeld.nl"></label><div id="form-error" class="inline-error"></div><div class="notice">${icon('shield')}Er wordt een demoprofiel aangemaakt. Je hebt geen wachtwoord nodig.</div><div class="modal-actions">${button('Annuleren','close-modal','ghost')}<button class="btn gold">${icon('check')} ${direct?'Speler toevoegen':'Aanmelding versturen'}</button></div></form>`);}
function roleModal(){showModal('Jouw plek in de club.','Probeer de app als beheerder of als speler. Dit zijn demorollen.',[['admin','shield','Beheerder','Danny · Toernooien, spelers en goedkeuringen'],['player','target','Speler','Rick · Toernooien ontdekken en scores invullen']].map(([id,ic,l,s])=>`<button class="role-card" data-action="set-role" data-role="${id}">${icon(ic)}<div><strong>${l} ${db.role===id?'· Actief':''}</strong><small>${s}</small></div>${icon('right','end')}</button>`).join('')+`<div style="margin-top:20px">${button(icon('plus')+' Nieuwe speler aanmelden','register','ghost block')}</div>`);}
function playerProfile(id){const p=totals(P(id));showModal(esc(p.name),'Clubspeler bij De Puinruimers',`<div class="modal-meta">${avatar(id,'lg')}${badge('Goedgekeurd','approved')}<span class="subtle-label">${esc(p.email)}</span></div><div class="profile-stats"><div><b>${p.avg.toFixed(1)}</b><small>GEMIDDELDE</small></div><div><b>${p.oneEighties}</b><small>180’ERS</small></div><div><b>${p.finish}</b><small>HOOGSTE FINISH</small></div></div><div class="stat-compare"><b>${p.played}</b><span>Gespeeld / gewonnen</span><b>${p.won}</b></div><p class="subtle-label">Voorbeeldseizoen 2026 · Nieuwe 180’ers en finishes uit jouw demowedstrijden tellen mee.</p><div class="modal-actions">${admin()?button(icon('edit')+' Profiel bewerken','edit-player','ghost',`data-id="${id}"`):''}${button('Sluiten','close-modal','gold')}</div>`);}
function applyTurn(doubleConfirmed=false,dartsOverride){const m=db.matches.find(m=>m.id===matchId);const v=document.getElementById('score-value');const val=v?v.value:scoreText;if(!/^\d{1,3}$/.test(val)){const e=document.getElementById('score-error');if(e)e.textContent='Vul een score tussen 0 en 180 in.';return;}const darts=dartsOverride??Number(document.getElementById('darts-count')?.value||3);const result=applyScore(m,Number(val),{darts,doubleConfirmed});if(result.error){document.getElementById('score-error').textContent=result.error;return;}if(result.needsDouble){scoreText=val;showModal('Zit de dubbel erin?','Bevestig de finish om deze leg af te sluiten.',`<div class="checkout"><small>Finishsuggestie voor ${m.remaining[m.turn]}</small>${checkout(m.remaining[m.turn])||'Dubbel uit'}</div><p class="subtle-label">${esc(short(m.players[m.turn]))} gooit ${val} uit met ${darts} dart${darts>1?'s':''}. Is de laatste dart een dubbel?</p><div class="modal-actions">${button('Nog niet','close-modal','ghost')}${button(icon('check')+' Ja, dubbel geraakt','confirm-double','gold',`data-darts="${darts}"`)}</div>`);return;}db.matches[db.matches.findIndex(x=>x.id===matchId)]={...result.match,tournament:m.tournament};if(result.winner)log(`${P(result.winner).name} wint op bord ${m.board}.`);save();scoreText='';closeModal();render();toast(result.winner?`${P(result.winner).name} wint de wedstrijd!`:result.legWon?'Leg gewonnen! De volgende leg staat klaar.':result.bust?'Bust! De score blijft staan.':`${val} genoteerd. ${short(result.match.players[result.match.turn])} is aan zet.`);}
function exportCSV(filename,rows){let content='\uFEFF'+rows.map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Het CSV-bestand wordt gedownload.');}
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay')){closeModal();return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);if(baan.action(b)){e.preventDefault();return;}if(a==='venue-sync-discard'){venueSync.discard();return;}if(venue.handleAction(a,b,e)||venueCast.handleAction(a,b,e))return;if(a==='portal-global-play'){switchScope('global',true);return;}if(portal.handleAction(a,b,e)||rooms.handleAction(a,b,e)||competitions.handleAction(a,b,e)||training.handleAction(a,b,e)||community.handleAction(a,b,e)||clubs.handleAction(a,b,e))return;if(a==='nav'||a.startsWith('nav-')){e.preventDefault();closeModal();go(a==='nav'?b.dataset.to:a.slice(4));return;}switch(a){
case 'toggle-menu':setMenu(!navOpen);break;
case 'skip-content':e.preventDefault();document.getElementById('main-content')?.focus();break;
case 'close-modal':closeModal();break;
case 'venue-open-event':{
  e.preventDefault();
  const result=ctx.selectVenueEvent(b.dataset.eventId);
  if(result.error){toast(result.error);break;}
  const target=['venue','venue/entries','venue/boards','venue/schedule','venue-cast/studio'].includes(b.dataset.to)?b.dataset.to:'venue';
  save();go(target);break;
}
case 'new-tour':tourForm();break;
case 'edit-tour':tourForm(id);break;
case 'tour-detail':tourDetail(id);break;
case 'tour-filter':tourFilter=b.dataset.value;render();break;
case 'request-filter':requestFilter=b.dataset.value;render();break;
case 'rank-filter':rankMetric=b.dataset.value;render();break;
case 'new-player':if(admin())registerForm(true);break;
case 'register':registerForm(false);break;
case 'role':roleModal();break;
case 'set-role':db.role=b.dataset.role;db.play.space=db.role==='admin'?'organizer':'player';save();closeModal();go(db.role==='admin'?'dashboard':'home');toast(admin()?'Je bekijkt de demo als beheerder.':'Je bekijkt de demo als Rick, speler.');break;
case 'tour-pools':selectedTour=id;closeModal();go('pools');break;
case 'join-tour':{const t=T(id);if(t.status!=='open'){toast('De inschrijving is gesloten.');break;}if(t.players>=t.capacity){toast('Dit toernooi zit vol.');break;}if(db.requests.some(r=>r.type==='entry'&&r.playerId===1&&r.tournament===id&&r.status!=='rejected')){toast('Rick is al aangemeld voor dit toernooi.');break;}db.requests.unshift({id:Date.now(),name:P(1).name,email:P(1).email,type:'entry',playerId:1,tournament:id,status:'pending',date:'Zojuist'});save();closeModal();render();toast('Rick is aangemeld. De beheerder kan het verzoek beoordelen.');break;}
case 'approve-request':case 'reject-request':{if(!admin())break;const r=db.requests.find(r=>r.id===id);if(r?.status!=='pending')break;if(a==='approve-request'&&r.type==='entry'&&T(r.tournament).players>=T(r.tournament).capacity){toast('Dit toernooi is vol. Vergroot eerst het aantal plaatsen.');break;}r.status=a==='approve-request'?'approved':'rejected';if(r.status==='approved'){if(r.type==='player'){const newId=Math.max(...db.players.map(p=>p.id))+1;db.players.push({id:newId,name:r.name,email:r.email,status:'approved',avg:0,oneEighties:0,finish:0,played:0,won:0});r.playerId=newId;}else T(r.tournament).players++;}log(`${r.name}: ${r.status==='approved'?'goedgekeurd':'afgewezen'}.`);save();render();toast(r.status==='approved'?'Aanmelding goedgekeurd.':'Aanmelding afgewezen.');break;}
case 'player-profile':playerProfile(id);break;
case 'edit-player':{if(!admin())break;const p=P(id);showModal('Profiel bewerken.','Werk de gegevens van deze clubspeler bij.',`<form data-form="edit-player"><input type="hidden" name="id" value="${id}"><label class="field">Volledige naam<input name="name" class="input" required maxlength="60" value="${esc(p.name)}"></label><label class="field">E-mailadres<input type="email" name="email" class="input" required maxlength="100" value="${esc(p.email)}"></label><div id="form-error" class="inline-error"></div><div class="modal-actions">${button('Annuleren','close-modal','ghost')}<button class="btn gold">Opslaan</button></div></form>`);break;}
case 'open-match':matchId=id;closeModal();go('match');break;
case 'key':{const k=b.dataset.key;const inp=document.getElementById('score-value');if(!inp)break;if(k==='ok'){applyTurn();break;}scoreText=k==='back'?inp.value.slice(0,-1):(inp.value+k).slice(0,3);inp.value=scoreText;document.getElementById('score-error').textContent='';break;}
case 'quick-score':scoreText=b.dataset.value;document.getElementById('score-value').value=scoreText;document.getElementById('score-error').textContent='';break;
case 'confirm-double':applyTurn(true,Number(b.dataset.darts));break;
case 'undo-score':{const ix=db.matches.findIndex(m=>m.id===matchId);const m=db.matches[ix];if(!m.history.length)break;db.matches[ix]={...undo(m),tournament:m.tournament};scoreText='';save();render();toast('De laatste beurt is teruggedraaid.');break;}
case 'score-rules':showModal('De spelregels.','Duidelijk aan de oche, duidelijk op het bord.',`<p class="subtle-label">Je begint bij 501 of 301. Elke beurt telt maximaal drie darts. Kies bij een finish hoeveel darts je hebt gebruikt.</p><p class="subtle-label">Je moet precies op nul eindigen, met een dubbel of de bull (50). Je bevestigt de dubbel bij een finish. Onder nul of één over? Bust: je score van vóór de beurt blijft staan.</p><p class="subtle-label">De winnaar van de meerderheid van de afgesproken legs wint de wedstrijd. De speler die een leg begint wisselt per leg.</p><div class="notice">${icon('info')}De bestaande score en legs zijn voorbeelddata. Nieuwe beurten worden volledig bijgehouden.</div><div class="modal-actions">${button('Helder, gooien maar','close-modal','gold')}</div>`);break;
case 'notifications':showModal('In de club.','Jouw meldingen en recente activiteiten.',db.settings.notifications?`<div class="notification-item"><strong>${pending()} openstaande aanmeldingen</strong><p>${admin()?'Er staan spelers en deelnameverzoeken voor je klaar.':'De beheerder beoordeelt alle nieuwe verzoeken.'}</p>${button('Bekijk aanmeldingen '+icon('right'),'nav-registrations','small ghost')}</div><div class="notification-item"><strong>Vrijdagavond Masters</strong><p>De inschrijving is open. Er zijn nog ${T(2).capacity-T(2).players} plaatsen beschikbaar.</p><small>6 november 2026 · 19:30 uur</small></div>${db.activity.map(x=>`<div class="notification-item"><strong>${esc(x)}</strong><small>Activiteit uit deze demo</small></div>`).join('')}`:`<div class="notice">${icon('bell')}Je hebt demo-meldingen uitgeschakeld bij Instellingen.</div>`);break;
case 'search':showModal('Zoeken in Dartflow','Vind een scherm, speler of toernooi in je huidige omgeving.',`<div class="input-wrap">${icon('search')}<input class="input" style="width:100%" id="global-search" placeholder="Typ om te zoeken…" aria-label="Zoeken in Dartflow"></div><div id="search-results">${searchResults()}</div>`);break;
case 'open-scoped-tournament':{
  if(!db.tournaments.some(t=>Number(t.id)===id&&inScope(t)))break;
  db.play.selectedHall=id;
  save();closeModal();go('hall');break;
}
case 'toggle-setting':db.settings[b.dataset.key]=!db.settings[b.dataset.key];save();render();break;
case 'reset-demo':showModal('Opnieuw beginnen?','Alle lokale wijzigingen, spelers en scores worden hersteld.',`<div class="modal-actions">${button('Annuleren','close-modal','ghost')}${button('Ja, demo herstellen','confirm-reset','danger')}</div>`);break;
case 'confirm-reset':rooms.stopMedia?.();db=seed();portal.init();community.init();save();closeModal();go('home');toast('De voorbeeldgegevens zijn hersteld.');break;
case 'shuffle-pools':if(admin()&&selectedTour===1)showModal('Nieuwe poules indelen?','De 24 spelers worden opnieuw over zes poules verdeeld. De voorbeeldstanden starten opnieuw.',`<div class="notice">${icon('info')}Deze demo-indeling heeft geen invloed op de vier lopende scoreborden of het losse knock-outvoorbeeld.</div><div class="modal-actions">${button('Annuleren','close-modal','ghost')}${button(icon('shuffle')+' Indeling maken','confirm-pools','gold')}</div>`);break;
case 'confirm-pools':{if(!admin()||selectedTour!==1)break;let ids=db.players.filter(p=>p.status==='approved').slice(0,24).map(p=>p.id);for(let i=ids.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]];}db.pools=Array.from({length:6},(_,i)=>ids.slice(i*4,i*4+4));save();closeModal();render();toast('Zes nieuwe poules zijn ingedeeld.');break;}
case 'advance-bracket':{if(!admin())break;let ix=db.knockout.findIndex(r=>r.some(m=>!m.winner));if(ix<0)break;db.knockout[ix].forEach((m,j)=>{const winnerIx=(j+ix)%2;const target=ix===2?4:3;m.score=winnerIx===0?[target,target-1]:[target-1,target];m.winner=m.players[winnerIx];if(ix<2)db.knockout[ix+1][Math.floor(j/2)].players[j%2]=m.winner;});save();render();toast(ix===2?`${P(db.knockout[2][0].winner).name} wint het voorbeeldtoernooi!`:'Uitslagen ingevuld. De winnaars gaan door.');break;}
case 'reset-bracket':if(admin()){db.knockout=seed().knockout;save();render();toast('Het knock-outvoorbeeld is hersteld.');}break;
case 'export-matches':exportCSV('puinruimers-uitslagen.csv',[['Bord','Speler 1','Speler 2','Legs 1','Legs 2','Resterend 1','Resterend 2','Status'],...db.matches.map(m=>[m.board,P(m.players[0]).name,P(m.players[1]).name,...m.legs,...m.remaining,m.status])]);break;
case 'export-ranking':exportCSV('puinruimers-ranglijst.csv',[['Positie','Speler','Gewonnen','Gemiddelde','180-ers','Hoogste finish'],...ranked().map((p,i)=>[i+1,p.name,p.won,p.avg,p.oneEighties,p.finish])]);break;
}});
document.addEventListener('input',e=>{baan.input(e);if(e.target.id==='dr-friend-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-friend-name]').forEach(el=>el.hidden=!el.dataset.friendName.includes(q));}if(e.target.id==='score-value'){scoreText=e.target.value.replace(/\D/g,'').slice(0,3);e.target.value=scoreText;document.getElementById('score-error').textContent='';}if(e.target.id==='player-search'){playerSearch=e.target.value;let visible=0;document.querySelectorAll('[data-search]').forEach(r=>{r.hidden=!r.dataset.search.includes(playerSearch.toLowerCase());if(!r.hidden)visible++;});document.getElementById('search-empty').hidden=visible>0;}if(e.target.id==='global-search')document.getElementById('search-results').innerHTML=searchResults(e.target.value);});
document.addEventListener('change',e=>{baan.change(e);if(e.target.matches('[data-scope-select]')){switchScope(e.target.value);return;}if(e.target.id==='selected-tour'){selectedTour=Number(e.target.value);render();}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const f=Object.fromEntries(new FormData(form));if(baan.form(form,f)||venue.handleForm(form,f,e)||portal.handleForm(form,f)||rooms.handleForm(form,f)||competitions.handleForm(form,f)||training.handleForm(form,f)||community.handleForm(form,f)||clubs.handleForm(form,f))return;const error=msg=>{let el=document.getElementById('form-error');if(el)el.textContent=msg;};if(form.dataset.form==='tournament'){if(!admin())return;const name=f.name.trim(),location=f.location.trim();if(!name||!location)return error('Vul een naam en locatie in.');if(Number(f.capacity)<(f.id?T(f.id).players:0))return error('Het maximum kan niet lager zijn dan het aantal deelnemers.');const values={name,date:f.date,format:f.format,status:f.status,capacity:Number(f.capacity),score:Number(f.score),bestOf:Number(f.bestOf),location,clubId:scopeId()};if(f.id)Object.assign(T(f.id),values);else db.tournaments.push({id:Date.now(),players:0,progress:0,...values});log(`Toernooi ${name} ${f.id?'gewijzigd':'aangemaakt'}.`);save();closeModal();go('tournaments');toast(f.id?'Toernooi bijgewerkt.':'Je nieuwe toernooi staat klaar.');}
if(form.dataset.form==='player'){let name=f.name.trim(),email=f.email.trim().toLowerCase();if(!name)return error('Vul je naam in.');if([...db.players,...db.requests.filter(r=>r.status!=='rejected')].some(p=>p.email.toLowerCase()===email))return error('Dit e-mailadres is al bekend in de demo.');if(f.direct==='true'&&admin()){db.players.push({id:Math.max(...db.players.map(p=>p.id))+1,name,email,status:'approved',avg:0,oneEighties:0,finish:0,played:0,won:0});save();closeModal();go('players');toast(`${name} is toegevoegd aan de club.`);}else{db.requests.unshift({id:Date.now(),name,email,type:'player',status:'pending',date:'Zojuist'});save();closeModal();render();toast('Aanmelding ontvangen! De beheerder kan je goedkeuren.');}}
if(form.dataset.form==='edit-player'){if(!admin())return;let name=f.name.trim(),email=f.email.trim().toLowerCase();if(!name)return error('Vul een naam in.');if(db.players.some(p=>p.id!==Number(f.id)&&p.email.toLowerCase()===email))return error('Dit e-mailadres wordt al gebruikt.');Object.assign(P(Number(f.id)),{name,email});save();closeModal();render();toast('Het spelersprofiel is bijgewerkt.');}
if(form.dataset.form==='settings'){if(!admin())return;if(!f.club.trim())return;Object.assign(db.settings,{club:f.club.trim(),location:f.location.trim(),email:f.email.trim(),score:Number(f.score),bestOf:Number(f.bestOf)});save();render();toast('De clubinstellingen zijn opgeslagen.');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();if(navOpen)setMenu(false);}if(e.key==='Enter'&&e.target.id==='score-value'){e.preventDefault();applyTurn();}if(e.key==='Enter'&&e.target.matches('tr[data-action]'))e.target.click();if(e.key==='Tab'){const modal=document.querySelector('.modal');if(!modal)return;const focus=[...modal.querySelectorAll('button:not(:disabled),input:not([type=hidden]),select,a[href]')];if(!focus.length)return;if(e.shiftKey&&(document.activeElement===focus[0]||document.activeElement===modal)){e.preventDefault();focus.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();focus[0].focus();}}});
const venueAssets = new Set(['public','checkin','board-B1','board-B2','board-B3','board-B4']);
function venueEvents() {
  const events = [db.venue, ...Object.values(db.venueSaved || {})];
  const club = scopeId();
  return events.filter(event => event === db.venue || (club == null || String(event.clubId) === String(club)));
}
function useVenueEvent(next) {
  db.venueSaved ||= {};
  db.venueSaved[db.venue.id] = db.venue;
  delete db.venueSaved[next.id];
  db.venue = next;
}
const ctx={
  scopedRegistrationRequests,
  baanRead,baanUrl,baanNewRoom:newBaanRoom,
  venueEvents,
  scopedVenueEvents:()=>venueEvents().filter(event=>String(event.clubId??'global')===String(scopeId()??'global')),
  createVenueEvent(options) {
    if (venueSync.offline()) return {error:'Verwerk eerst de lokale scorebuffer.'};
    const result = venueAction(db.venue, 'new-event', {...options, id: `venue-${crypto.randomUUID()}`});
    if (!result.error) useVenueEvent(result.state);
    return result;
  },
  selectVenueEvent(id) {
    if (venueSync.offline()) return {error:'Verwerk eerst de lokale scorebuffer.'};
    if (String(db.venue.id) === String(id)) return {};
    const event = venueEvents().find(item => String(item.id) === String(id));
    if (!event) return {error:'Deze speeldag is hier niet beschikbaar.'};
    useVenueEvent(event);
    return {};
  },
  venueDispatch:(action,payload,now)=>venueSync.dispatch(action,payload,now),
  venueOffline:()=>venueSync.offline(),
  venueOfflineInfo:()=>venueSync.info(),
  venueGame:match=>venueSync.game(match),
  setVenueOffline:enabled=>venueSync.setOffline(enabled),
  venueUrl:target=>new URL('#'+target,location.href).href,
  venueQr:target=>venueAssets.has(target)?'assets/venue-'+target+'-qr.svg':null,
  get db(){return db;},icon,esc,P,T,short,avatar,badge,button,header,metric,sectionHeading,empty,toast,save,showModal,closeModal,go,render,admin,date,roomId:()=>matchId,scopeId,scopeName,routeParam:()=>pageParam,get baseUrl(){return location.origin;},openMatch:id=>{matchId=Number(id);go('match');},createGame:options=>rooms.createGame(options),createCommunityRoom:options=>community.createRoom(options),renderPools:id=>{selectedTour=Number(id);return pools(true);},onFinished:match=>competitions.onFinished(match)};
rooms=createRooms(ctx);competitions=createCompetitions(ctx);training=createTraining(ctx);community=createCommunity(ctx);clubs=createClubs(ctx);portal=createPortal(ctx,rooms,competitions,training);venue=createVenue(ctx);
venueCast=createVenueCast(ctx);
venueSync=createVenueOffline(ctx);
const baan=createBaan({render,toast,escape:esc});
portal.init();community.init();clubs.init();venue.init();
window.addEventListener('storage',event=>{if(event.key!=='puinruimers-demo-v3'||!event.newValue)return;try{const next=JSON.parse(event.newValue);if(next.version!==3)return;db=next;portal.init();community.init();clubs.init();render();}catch{}});
window.addEventListener('beforeunload',()=>rooms.stopMedia?.());
window.addEventListener('offline',()=>{
  if(route==='venue'&&pageParam.startsWith('board-')) venueSync.setOffline(true);
});
window.addEventListener('online',()=>{
  if(venueSync.offline()) venueSync.setOffline(false);
});
setInterval(()=>{
  venue.tick?.();
  venueCast.tick?.();
  if(!db.venue||venueSync.offline()||route!=='venue'&&!(route==='venue-cast'&&pageParam==='studio')) return;
  const previous=JSON.stringify(db.venue);
  const result=venueSync.dispatch('tick');
  if(result.error||JSON.stringify(result.state)===previous) return;
  db.venue=result.state;
  save();
  render();
},1000);
render();

